<script setup lang="ts">import {onMounted,ref} from 'vue';import {api,dateTime,messageOf} from '@/lib/api';import StatusBadge from '@/components/StatusBadge.vue';const versions=ref<any[]>([]),showImport=ref(false),loading=ref(false),error=ref(''),form=ref({name:'Classificação Tributária NCM × cClassTrib',version:'',valid_from:'2026-01-01',base_version_id:''}),file=ref<File>();async function load(){versions.value=(await api.get('/catalogs')).data.data}onMounted(load);async function send(){if(!file.value)return;loading.value=true;error.value='';try{const fd=new FormData();Object.entries(form.value).forEach(([k,v])=>v&&fd.append(k,v));fd.append('file',file.value);await api.post('/catalogs/import',fd);showImport.value=false;await load()}catch(e){error.value=messageOf(e)}finally{loading.value=false}}</script><template><section class="card"><div class="card-title"><div><h2>Catálogos NCM × ClassTrib</h2><p>Versões persistidas no PostgreSQL. Planilhas servem apenas para importação controlada.</p></div><button class="primary" @click="showImport=!showImport">Importar nova planilha</button></div><form v-if="showImport" class="import-box form-grid" @submit.prevent="send"><label>Nome<input v-model="form.name" required/></label><label>Versão<input v-model="form.version" placeholder="2026.08.01-r1" required/></label><label>Vigência inicial<input v-model="form.valid_from" type="date" required/></label><label>Base oficial<select v-model="form.base_version_id"><option value="">Versão publicada atual</option><option v-for="v in versions" :value="v.id">{{v.version}}</option></select></label><label class="span-2">Planilha XLSX<input type="file" accept=".xlsx" @change="file=($event.target as HTMLInputElement).files?.[0]" required/></label><p class="error span-2" v-if="error">{{error}}</p><div class="span-2"><button class="primary" :disabled="loading">{{loading?'Importando...':'Validar e importar'}}</button></div></form><table><thead><tr><th>Versão</th><th>Nome</th><th>Status</th><th>Vigência</th><th>Linhas</th><th>Críticas da fonte</th><th>Publicado em</th></tr></thead><tbody><tr v-for="v in versions" :key="v.id" class="clickable" @click="$router.push(`/catalogos/${v.id}`)"><td><strong>{{v.version}}</strong></td><td>{{v.name}}</td><td><StatusBadge :value="v.status"/></td><td>{{v.valid_from||'—'}}</td><td>{{v.ncm_entries_count}}</td><td>{{v.issues_count}}</td><td>{{dateTime(v.published_at)}}</td></tr></tbody></table></section></template>
